#rf-root,.hf-root{--x3:#4a5447;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-fadeout 0.5s ease-in 5s both;}.cam{position:absolute;inset:0;animation:st-cam 5.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}@property --n74{syntax:'<integer>';inherits:false;initial-value:0}
.n74{counter-reset:n74 var(--n74);animation:n74-c 1.4s cubic-bezier(.16,1,.3,1) 0.7s both}
.n74::after{content:counter(n74,decimal)}
@keyframes n74-c{from{--n74:0}to{--n74:15}}.rc-hd{position:absolute;left:90px;right:90px;top:260px;font-size:100px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:.98}
.bowl{position:absolute;left:50%;top:580px;width:640px;height:640px;margin-left:-320px}
.plate{position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 40% 35%,#ffffff,#e9e6df 60%,#cfc9bd);box-shadow:0 40px 80px -30px rgba(0,0,0,.5),inset 0 0 0 40px rgba(255,255,255,.55);animation:k-pop .8s cubic-bezier(.16,1,.3,1) 0.2s both}
.food{position:absolute;left:60px;top:60px;width:500px;height:500px}
.food i{position:absolute;box-shadow:inset -10px -12px 0 rgba(0,0,0,.12);animation:k-pop .6s cubic-bezier(.16,1,.3,1) both}
.steam{position:absolute;left:0;right:0;top:-220px;height:240px;display:flex;justify-content:center;gap:70px}
.steam b{width:26px;height:200px;border-radius:30px;background:linear-gradient(transparent,color-mix(in srgb,var(--rf-text) 30%,transparent));animation:sm 2.2s ease-in-out infinite both}
.steam b:nth-child(2){animation-delay:-.7s}.steam b:nth-child(3){animation-delay:-1.4s}
@keyframes sm{0%{transform:translateY(60px) scaleY(.6);opacity:0}50%{opacity:.8}100%{transform:translateY(-60px) scaleY(1.1);opacity:0}}
.tm{position:absolute;right:80px;top:1100px;width:230px;height:230px;border-radius:50%;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 8%,transparent)}
.tm svg{position:absolute;inset:15px;transform:rotate(-90deg)}
.tt{fill:none;stroke:color-mix(in srgb,var(--rf-text) 12%,transparent);stroke-width:10}
.tv{fill:none;stroke:var(--rf-accent);stroke-width:10;stroke-linecap:round;stroke-dasharray:100;stroke-dashoffset:100;animation:tvv 4.4s linear 0.6s both}
@keyframes tvv{to{stroke-dashoffset:20}}
.tm div{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}
.tm b{font:600 76px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace}.tm small{font:600 24px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted);}
.igs{position:absolute;left:80px;right:80px;top:1320px;display:flex;flex-wrap:wrap;gap:18px}
.ig{font-size:38px;font-weight:500;padding:20px 30px;border-radius:20px;background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 12%,transparent)}

